using Xunit;

public class VirtualClinicTests
{
    [Fact]
    public void TC_001_SpecialityWiseNumberOfConsultationsByDoctor()
    {
        // Arrange
        var doctorId = "D123";
        var month = "2023-04";
        var speciality = "Cardiology";

        // Act
        var numberOfConsultations = VirtualClinic.GetNumberOfConsultationsByDoctor(doctorId, month, speciality);

        // Assert
        Assert.IsType<int>(numberOfConsultations);
        Assert.True(numberOfConsultations >= 0);
    }

    [Fact]
    public void TC_002_SpecialityWiseRevenueEarnedPerMonth()
    {
        // Arrange
        var speciality = "Cardiology";
        var month = "2023-04";

        // Act
        var revenue = VirtualClinic.GetRevenueEarnedPerMonth(speciality, month);

        // Assert
        Assert.IsType<decimal>(revenue);
        Assert.True(revenue >= 0);
    }

    [Fact]
    public void TC_003_PatientHistoryFileBasedOnPatientId()
    {
        // Arrange
        var patientId = "P456";

        // Act
        var patientHistory = VirtualClinic.GetPatientHistoryFile(patientId);

        // Assert
        Assert.NotNull(patientHistory);
        Assert.IsType<PatientHistory>(patientHistory);
    }

    [Fact]
    public void TC_004_PatientCreatesConsultationRequest()
    {
        // Arrange
        var patientId = "P456";
        var symptoms = "Fever, Cough";
        var mode = ConsultationMode.Appointment;

        // Act
        var consultationRequest = VirtualClinic.CreateConsultationRequest(patientId, symptoms, mode);

        // Assert
        Assert.NotNull(consultationRequest);
        Assert.IsType<ConsultationRequest>(consultationRequest);
        Assert.Equal(patientId, consultationRequest.PatientId);
        Assert.Equal(symptoms, consultationRequest.Symptoms);
        Assert.Equal(mode, consultationRequest.Mode);
    }

    [Fact]
    public void TC_005_PatientCreatesOfflineConsultationRequest()
    {
        // Arrange
        var patientId = "P456";
        var symptoms = "Fever, Cough";
        var mode = ConsultationMode.Offline;

        // Act
        var consultationRequest = VirtualClinic.CreateConsultationRequest(patientId, symptoms, mode);

        // Assert
        Assert.NotNull(consultationRequest);
        Assert.IsType<ConsultationRequest>(consultationRequest);
        Assert.Equal(patientId, consultationRequest.PatientId);
        Assert.Equal(symptoms, consultationRequest.Symptoms);
        Assert.Equal(mode, consultationRequest.Mode);
    }

    [Fact]
    public void TC_006_PatientCreatesConsultationRequestWithReports()
    {
        // Arrange
        var patientId = "P456";
        var symptoms = "Fever, Cough";
        var mode = ConsultationMode.Appointment;
        var reports = new List<Report> { new Report { Type = "X-ray", Result = "Normal" } };

        // Act
        var consultationRequest = VirtualClinic.CreateConsultationRequest(patientId, symptoms, mode, reports);

        // Assert
        Assert.NotNull(consultationRequest);
        Assert.IsType<ConsultationRequest>(consultationRequest);
        Assert.Equal(patientId, consultationRequest.PatientId);
        Assert.Equal(symptoms, consultationRequest.Symptoms);
        Assert.Equal(mode, consultationRequest.Mode);
        Assert.Equal(reports, consultationRequest.Reports);
    }

    [Fact]
    public void TC_007_BatchProgramCreatesAppointmentFileForNextDay()
    {
        // Arrange
        var appointmentDate = DateTime.Now.AddDays(1);

        // Act
        VirtualClinic.CreateAppointmentFileForNextDay(appointmentDate);

        // Assert
        // Assuming there's a way to verify the appointment file is created
        // For example, checking if a file exists in a specific directory
        Assert.True(File.Exists("path/to/appointment/file"));
    }

    [Fact]
    public void TC_008_BatchProgramPurgesExistingAppointmentFiles()
    {
        // Arrange
        var appointmentDate = DateTime.Now.AddDays(1);

        // Act
        VirtualClinic.CreateAppointmentFileForNextDay(appointmentDate);
        VirtualClinic.PurgeExistingAppointmentFiles();

        // Assert
        // Assuming there's a way to verify the appointment file is purged
        // For example, checking if a file exists in a specific directory
        Assert.False(File.Exists("path/to/appointment/file"));
    }

    [Fact]
    public void TC_009_BatchProgramPredictsDiseasesAndPrioritizesRequests()
    {
        // Arrange
        var consultationRequest = new ConsultationRequest { PatientId = "P456", Symptoms = "Fever, Cough" };

        // Act
        VirtualClinic.PredictDiseasesAndPrioritizeRequests(consultationRequest);

        // Assert
        // Assuming there's a way to verify the request is prioritized
        // For example, checking if the request has a priority level
        Assert.NotNull(consultationRequest.Priority);
    }

    [Fact]
    public void TC_010_DoctorSeesPrioritizedConsultationRequests()
    {
        // Arrange
        var consultationRequest = new ConsultationRequest { PatientId = "P456", Symptoms = "Fever, Cough", Priority = Priority.Critical };

        // Act
        var doctor = VirtualClinic.GetDoctorForConsultationRequest(consultationRequest);

        // Assert
        Assert.NotNull(doctor);
        Assert.IsType<Doctor>(doctor);
        Assert.Equal(Priority.Critical, consultationRequest.Priority);
    }

    [Fact]
    public void TC_011_DoctorProvidesDiagnosisAndPrescribesMedicines()
    {
        // Arrange
        var consultationRequest = new ConsultationRequest { PatientId = "P456", Symptoms = "Fever, Cough", Priority = Priority.Critical };
        var doctor = VirtualClinic.GetDoctorForConsultationRequest(consultationRequest);

        // Act
        var diagnosis = doctor.ProvideDiagnosis(consultationRequest);
        var prescription = doctor.PrescribeMedicines(consultationRequest);

        // Assert
        Assert.NotNull(diagnosis);
        Assert.IsType<Diagnosis>(diagnosis);
        Assert.NotNull(prescription);
        Assert.IsType<Prescription>(prescription);
    }

    [Fact]
    public void TC_012_DoctorSuggestsLabRequests()
    {
        // Arrange
        var consultationRequest = new ConsultationRequest { PatientId = "P456", Symptoms = "Fever, Cough", Priority = Priority.Critical };
        var doctor = VirtualClinic.GetDoctorForConsultationRequest(consultationRequest);

        // Act
        var labRequests = doctor.SuggestLabRequests(consultationRequest);

        // Assert
        Assert.NotNull(labRequests);
        Assert.IsType<List<LabRequest>>(labRequests);
    }

    [Fact]
    public void TC_013_ChemistViewsOpenPrescriptions()
    {
        // Arrange
        var prescription = new Prescription { Id = "P123", Status = PrescriptionStatus.Open };

        // Act
        var chemist = VirtualClinic.GetChemistForPrescription(prescription);

        // Assert
        Assert.NotNull(chemist);
        Assert.IsType<Chemist>(chemist);
        Assert.Equal(PrescriptionStatus.Open, prescription.Status);
    }

    [Fact]
    public void TC_014_ChemistUpdatesPrescriptionStatus()
    {
        // Arrange
        var prescription = new Prescription { Id = "P123", Status = PrescriptionStatus.Open };
        var chemist = VirtualClinic.GetChemistForPrescription(prescription);

        // Act
        chemist.UpdatePrescriptionStatus(prescription, PrescriptionStatus.Completed);

        // Assert
        Assert.Equal(PrescriptionStatus.Completed, prescription.Status);
    }

    [Fact]
    public void TC_015_ChemistDeliversMedicinesOffline()
    {
        // Arrange
        var prescription = new Prescription { Id = "P123", Status = PrescriptionStatus.Completed };
        var chemist = VirtualClinic.GetChemistForPrescription(prescription);

        // Act
        chemist.DeliverMedicinesOffline(prescription);

        // Assert
        // Assuming there's a way to verify the medicines are delivered
        // For example, checking if a delivery record is created
        Assert.True(File.Exists("path/to/delivery/record"));
    }
}
